import 'package:dio/dio.dart';import 'package:flutter/widgets.dart';import 'package:zan/Core/Storage/Remote/api_password.dart';import 'api_endpoints.dart';import 'api_interceptor.dart';class DioHelper {  static late Dio dio;  static void init(String state) {    dio = Dio(      BaseOptions(        baseUrl: ApiEndpoints.baseUrl,        receiveDataWhenStatusError: true,        connectTimeout: const Duration(seconds: 10),        receiveTimeout: const Duration(seconds: 10),        headers: {          'Content-Type': 'application/json',          // "language": state,        },        queryParameters: {          'api_password': ApiPassword.password        },      ),    );    dio.interceptors.add(ApiInterceptor());    dio.interceptors.add(InterceptorsWrapper(      onRequest: (options, handler) {        options.queryParameters['api_password'] = ApiPassword.password;        return handler.next(options);      },    ));    dio.interceptors.add(      LogInterceptor(        request: true,        requestHeader: true,        requestBody: true,        responseHeader: true,        responseBody: true,        error: true,      ),    );  }  static Future<Response?> getData({    required String path,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.get(path, queryParameters: queryParameters);    } catch (e) {      debugPrint('❌ GET Error: $e');      return null;    }  }  /// Handles POST requests  static Future<Response?> postData({    required String path,    required dynamic data,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.post(path, data: data, queryParameters: queryParameters);    } catch (e) {      debugPrint('❌ POST Error: $e');      return null;    }  }  /// Handles PUT requests  static Future<Response?> putData({    required String path,    required Map<String, dynamic> data,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.put(path, data: data, queryParameters: queryParameters);    } catch (e) {      debugPrint('❌ PUT Error: $e');      return null;    }  }  /// Handles DELETE requests  static Future<Response?> deleteData({    required String path,    Map<String, dynamic>? queryParameters,  }) async {    try {      return await dio.delete(path, queryParameters: queryParameters);    } catch (e) {      debugPrint('❌ DELETE Error: $e');      return null;    }  }}